import sys
sys.setrecursionlimit(10000)

n = int(sys.stdin.read().split()[0])
M = 10**9 + 7

def bit(r, c):
    return 1 << (2 * c + r)

pieces = []
for c in range(n):
    pieces.append(bit(0, c) | bit(1, c))
    if c + 1 < n:
        block = [(0, c), (1, c), (0, c + 1), (1, c + 1)]
        pieces.append(sum(bit(r, cc) for r, cc in block))
        for skip in range(4):
            pieces.append(sum(bit(r, cc) for k, (r, cc) in enumerate(block) if k != skip))

full = (1 << (2 * n)) - 1
memo = {}

def count(mask):
    if mask == full:
        return 1
    if mask in memo:
        return memo[mask]
    low = (~mask) & (mask + 1)
    total = 0
    for p in pieces:
        if p & low and not (p & mask):
            total += count(mask | p)
    memo[mask] = total
    return total

print(count(0) % M)

